CREATE TABLE ordenes_fila_orden_cambios (
  id INTEGER NOT NULL ,
  cambio TEXT NOT NULL ,
  fecha_cambio timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id)
);
CREATE TABLE ordenes_fila_reposiciones (
